# optiplex-backup-restore: body of the script. The header (SQLITE, PG_DBS, MARIADB_DBS) is generated by
# machines/optiplex/services/restic.nix, which also runs shellcheck on the whole.
#
# Variables from the header: SQLITE (associative array: copy name -> live path), PG_DBS, MARIADB_DBS.

usage() {
  cat <<'USAGE'
optiplex-backup-restore: put a restic snapshot of the Optiplex back (disaster recovery, yearly drill).

  optiplex-backup-restore [--snapshot <id|latest>] [--from <dir>] [--workdir <dir>]
                          [--hostkeys] [--no-db] [--help]

Run as root on the optiplex-restore install (nixosConfigurations.optiplex-restore: PostgreSQL and
MariaDB run and are empty, every Kept service is off), after nixos-anywhere has put the host keys
back, so the sops secrets (and with them `restic-optiplex`) work. Without them, restore from any
machine with the restic password and the bucket keys (infra/scaleway/README.md) and use --from.

What it does
  1. restic restore <snapshot> into <workdir> (default /mnt/tbssd/backup-restore, on the Data disk, so
     the State below can be moved into place instead of copied). The restic command is
     $OPTIPLEX_RESTIC (default `restic-optiplex`, the wrapper with the repository and credentials).
     --from <dir> skips this and uses a tree you restored yourself (restic restore ... --target <dir>).
  2. /state: every top-level directory of the snapshot's /state is moved into /state/<name>
     (ids are numeric and pinned, nothing is chowned). Refuses when /state already holds anything but
     postgresql, mariadb and lost+found: never restore over data.
  3. /var/backup (the dumps and the SQLite copies) and /mnt/tbssd/archive are rsynced into place.
  4. The SQLite databases of Vaultwarden, etesync, Home Assistant and healthchecks are not part of the
     snapshot as live files: their consistent copies from /var/backup/sqlite/ are checked
     (PRAGMA integrity_check) and put where the live files belong, owned like their directory.
  5. The database dumps in /var/backup/{postgresql,mysql} are staged under their restore names and
     loaded with `optiplex-db-restore --no-manifest` (all eight databases, small ones first).
     --no-db stops before that.
  6. --hostkeys also installs the host keys from the snapshot (ssh_host_*, the initrd key) when absent.
  Then the work directory is left in place (it also holds the host keys): remove it yourself.

What is not restored: /state/postgresql and /state/mariadb (the dumps are), anything the excludes
leave out (caches and logs: the services rebuild them), Seafile's Docker image (rebuilt by Nix).
Afterwards deploy normally: nixos-rebuild --flake .#optiplex. Never start a service against an empty
database; this script refuses to leave one behind (optiplex-db-restore checks every database).
USAGE
}

die() {
  echo "optiplex-backup-restore: $*" >&2
  exit 1
}
log() { echo ">> $*"; }

snapshot=latest
from=""
work=/mnt/tbssd/backup-restore
hostkeys=0
no_db=0
while (($#)); do
  case "$1" in
    --snapshot) snapshot="${2:?--snapshot needs an id}"; shift ;;
    --from) from="${2:?--from needs a directory}"; shift ;;
    --workdir) work="${2:?--workdir needs a directory}"; shift ;;
    --hostkeys) hostkeys=1 ;;
    --no-db) no_db=1 ;;
    -h | --help) usage; exit 0 ;;
    *) usage >&2; exit 2 ;;
  esac
  shift
done

[[ $EUID -eq 0 ]] || die "run as root"
mountpoint -q /state || die "/state is not mounted (Data disk missing?)"
mountpoint -q /mnt/tbssd || die "/mnt/tbssd is not mounted"
unexpected="$(find /state -mindepth 1 -maxdepth 1 ! -name postgresql ! -name mariadb ! -name lost+found -print -quit)"
[[ -z $unexpected ]] || die "/state already holds $unexpected: never restore over data"

# --- 1. the snapshot ------------------------------------------------------------------------------
if [[ -n $from ]]; then
  [[ -d $from/state ]] || die "$from has no state/ (restore with --target $from, snapshot paths are absolute)"
  work="$from"
else
  [[ ! -e $work ]] || [[ -z "$(ls -A "$work")" ]] || die "$work is not empty"
  log "restic restore $snapshot -> $work"
  # shellcheck disable=SC2086 # OPTIPLEX_RESTIC may carry arguments
  ${OPTIPLEX_RESTIC:-restic-optiplex} restore "$snapshot" --target "$work"
fi
[[ -d $work/state ]] || die "the snapshot has no /state"

# --- 2. State -------------------------------------------------------------------------------------
# Rename, not copy: the work directory and /mnt/tbssd/state are on the same filesystem, but /state is a
# separate (bind) mount, so the move goes through its source directory.
log "moving State into place"
shopt -s dotglob nullglob
for d in "$work"/state/*; do
  name="$(basename "$d")"
  [[ ! -e /mnt/tbssd/state/$name ]] || die "/state/$name exists"
  mv "$d" "/mnt/tbssd/state/$name"
done
shopt -u dotglob nullglob

# --- 3. dumps, SQLite copies, archive -----------------------------------------------------------------
if [[ -d $work/var/backup ]]; then
  log "rsync /var/backup"
  install -d -m 0755 /var/backup
  rsync -a "$work/var/backup/" /var/backup/
fi
if [[ -d $work/mnt/tbssd/archive ]]; then
  log "rsync /mnt/tbssd/archive"
  install -d /mnt/tbssd/archive
  rsync -a "$work/mnt/tbssd/archive/" /mnt/tbssd/archive/
fi

# --- 4. SQLite -------------------------------------------------------------------------------------------
for name in "${!SQLITE[@]}"; do
  live="${SQLITE[$name]}"
  copy="/var/backup/sqlite/$name.sqlite3"
  [[ -f $copy ]] || die "no SQLite copy $copy in the snapshot (the live file $live is not in it)"
  # on a scratch copy: opening a WAL-mode file would leave -wal/-shm files next to it
  chk="$(mktemp)"
  cp "$copy" "$chk"
  result="$(sqlite3 "$chk" 'PRAGMA integrity_check')"
  rm -f "$chk" "$chk-wal" "$chk-shm"
  [[ $result == ok ]] || die "$copy fails the integrity check"
  dir="$(dirname "$live")"
  install -d "$dir"
  rm -f "$live" "$live-wal" "$live-shm" "$live-journal"
  install -o "$(stat -c %u "$dir")" -g "$(stat -c %g "$dir")" -m 0600 "$copy" "$live"
  log "SQLite: $name -> $live"
done

# --- host keys --------------------------------------------------------------------------------------
if ((hostkeys)); then
  for f in "$work"/etc/ssh/ssh_host_* "$work"/etc/secrets/initrd/ssh_host_*; do
    [[ -f $f ]] || continue
    dest="${f#"$work"}"
    if [[ -e $dest ]]; then
      echo "host key $dest exists, left alone"
    else
      install -D -m "$([[ $f == *.pub ]] && echo 0644 || echo 0600)" -o root -g root "$f" "$dest"
      echo "host key $dest installed"
    fi
  done
fi

# --- databases ------------------------------------------------------------------------------------------
if ((no_db)); then
  log "--no-db: databases not loaded"
  exit 0
fi
# postgresqlBackup writes <db>.sql (custom format, no compression) and mysqlBackup writes <db>.gz;
# optiplex-db-restore reads <db>.dump and <db>.sql.gz.
staging="$(mktemp -d /run/optiplex-backup-restore.XXXXXX)"
trap 'rm -rf "$staging"' EXIT
mkdir "$staging/postgresql" "$staging/mariadb"
for db in "${PG_DBS[@]}"; do
  [[ -f /var/backup/postgresql/$db.sql ]] || die "no dump /var/backup/postgresql/$db.sql in the snapshot"
  ln -s "/var/backup/postgresql/$db.sql" "$staging/postgresql/$db.dump"
done
for db in "${MARIADB_DBS[@]}"; do
  [[ -f /var/backup/mysql/$db.gz ]] || die "no dump /var/backup/mysql/$db.gz in the snapshot"
  ln -s "/var/backup/mysql/$db.gz" "$staging/mariadb/$db.sql.gz"
done
log "optiplex-db-restore (the dumps of the snapshot)"
optiplex-db-restore --no-manifest "$staging"
echo "done. Next: remove $work when satisfied, then deploy: nixos-rebuild --flake .#optiplex"
